#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>

class HashingSolutions {
public:
    // 1. Two Sum (Complement Lookup)
    std::vector<int> twoSum(std::vector<int>& nums, int target) {
        std::unordered_map<int, int> seen; // value -> index

        for (int i = 0; i < nums.size(); i++) {
            int complement = target - nums[i];
            // Check if complement is in the map
            if (seen.find(complement) != seen.end()) {
                return {seen[complement], i}; // Found pair!
            }
            seen[nums[i]] = i; // Store current number
        }
        return {};
    }

    // 2. Group Anagrams (Canonical Mapping)
    std::vector<std::vector<std::string>> groupAnagrams(std::vector<std::string>& strs) {
        std::unordered_map<std::string, std::vector<std::string>> groups;

        for (std::string s : strs) {
            std::string signature = s;
            std::sort(signature.begin(), signature.end()); // e.g. "tea" becomes "aet"
            groups[signature].push_back(s); // Group it
        }

        std::vector<std::vector<std::string>> result;
        for (auto pair : groups) {
            result.push_back(pair.second);
        }
        return result;
    }
};
